'use strict';
const defaultLinkCategories=['包装','VI','建模','动画'];
let linkCategoryFilter='all';
function ensureLinkLibrary(){if(!Array.isArray(data.links))data.links=[];if(!Array.isArray(data.linkCategories))data.linkCategories=[...defaultLinkCategories]}
function normalizedLinkURL(raw){let value=String(raw||'').trim();if(value&&!/^[a-z][a-z\d+.-]*:/i.test(value))value='https://'+value;let result=safeURL(value);if(result==='#')throw Error('请输入有效的 http 或 https 网址 / Enter a valid HTTP or HTTPS URL.');return result}
function validLinkThumbnail(value){return !value||safeURL(value)!=='#'||(/^data:image\/(webp|png|jpeg);base64,[a-z\d+/=]+$/i.test(value)&&value.length<=250000)}
function linkThumb(item){let url=new URL(item.url),custom=!!item.thumbnail;return `<div class="website-thumb ${custom?'custom-thumb':''}"><span class="website-monogram">${esc(item.title.slice(0,1).toUpperCase())}</span><img src="${esc(custom?item.thumbnail:url.origin+'/favicon.ico')}" class="${custom?'website-cover':'website-favicon'}" alt="${esc(item.title)}缩略图" loading="lazy" referrerpolicy="no-referrer"><span class="website-host">${esc(url.hostname)}</span></div>`}
function renderLinks(){ensureLinkLibrary();if(!data.linkCategories.includes(linkCategoryFilter))linkCategoryFilter='all';let items=data.links.filter(x=>(linkCategoryFilter==='all'||x.category===linkCategoryFilter)&&(!query||[x.title,x.url,x.notes,x.category].join(' ').toLowerCase().includes(query.toLowerCase())));return `<div class="view-toolbar"><div class="pills"><button class="pill ${linkCategoryFilter==='all'?'active':''}" data-link-category="all">全部网址 <span class="tab-count">${data.links.length}</span></button>${data.linkCategories.map(c=>`<button class="pill ${linkCategoryFilter===c?'active':''}" data-link-category="${esc(c)}">${esc(c)} <span class="tab-count">${data.links.filter(l=>l.category===c).length}</span></button>`).join('')}</div><button class="secondary" id="manageLinkCategories">管理分类</button></div><div class="notice">${icon('bookmark')}<span>保存常用设计网址，按用途整理。默认尝试显示站点图标；可上传截图或设置图片链接作为缩略图。<small class="system-en">Links and custom thumbnails are saved in this workspace and included in JSON backups.</small></span></div><div class="website-grid">${items.map(l=>`<article class="website-card"><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer" aria-label="打开 ${esc(l.title)}">${linkThumb(l)}</a><div class="website-body"><div class="website-category">${esc(l.category)}</div><h3><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.title)} ↗</a></h3><p>${esc(l.notes||'暂无备注')}</p><div class="website-actions"><button class="text-button" data-edit-link="${esc(l.id)}">编辑 / 修改缩略图</button><a class="text-button" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">打开网址 ↗</a></div></div></article>`).join('')||`<section class="panel website-empty">${empty('还没有保存的网址。添加常用网站，建立你的设计网址库。')}<button class="primary" id="emptyNewLink">＋ 保存第一个网址</button></section>`}</div>`}
function bindLinks(){if(view!=='links')return;$$('[data-link-category]').forEach(b=>b.onclick=()=>{linkCategoryFilter=b.dataset.linkCategory;render()});$$('[data-edit-link]').forEach(b=>b.onclick=()=>linkModal(b.dataset.editLink));$('#manageLinkCategories').onclick=manageLinkCategories;if($('#emptyNewLink'))$('#emptyNewLink').onclick=()=>linkModal();$$('.website-thumb img').forEach(img=>{img.addEventListener('error',()=>{img.hidden=true;img.closest('.website-thumb').classList.add('thumb-unavailable')});img.addEventListener('load',()=>img.closest('.website-thumb').classList.add('thumb-loaded'));if(img.complete){if(!img.naturalWidth)img.hidden=true;else img.closest('.website-thumb').classList.add('thumb-loaded')}})}
async function shrinkLinkThumbnail(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1048576)throw Error('请选择 10 MB 以内的 JPEG、PNG 或 WebP / Choose a JPEG, PNG or WebP under 10 MB.');let image=await createImageBitmap(file);try{if(image.width*image.height>50000000)throw Error('图片过大，请先缩小 / Resize this image first.');let scale=Math.min(1,720/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);for(let q of [.8,.6,.4,.2]){let url=canvas.toDataURL('image/webp',q);if(url.length<=250000)return url}throw Error('缩略图仍太大，请选择较简单的图片 / Choose a smaller or simpler image.')}finally{image.close()}}
function linkModal(linkId){ensureLinkLibrary();let existing=data.links.find(x=>x.id===linkId),item=existing||{title:'',url:'',category:linkCategoryFilter==='all'?data.linkCategories[0]:linkCategoryFilter,thumbnail:'',notes:''},imageValue=item.thumbnail||'',uploading=false,modalSpace=space,modalToken=id();openModal(existing?'编辑网址与缩略图':'保存设计网址',`<form id="linkForm" data-modal-token="${modalToken}"><div class="form-grid">${field('网址 / Website URL','url',item.url,'text',true,'required maxlength="2000" placeholder="https://example.com"')}${field('名称 / Name','title',item.title,'text',false,'required maxlength="100"')}${selectField('用途分类 / Category','category',data.linkCategories,item.category)}${textField('备注 / Notes','notes',item.notes)}<div class="field full">缩略图 / Thumbnail<div class="link-thumb-preview" id="linkThumbPreview"></div><label class="secondary thumb-upload" for="linkThumbFile">${icon('upload')}上传截图 / Upload image</label><input type="file" id="linkThumbFile" accept="image/jpeg,image/png,image/webp" class="hidden"><label class="field">或填写图片链接 / Image URL<input type="url" id="linkThumbURL" placeholder="https://…/preview.jpg" value="${esc(imageValue.startsWith('data:')?'':imageValue)}" maxlength="2000"></label><button type="button" class="text-button" id="resetLinkThumb">恢复站点图标 / Use site icon</button><small class="subtle">上传图片会本地缩小保存，不上传服务器。外部图片不可用时显示站点首字母。<br>Images are resized locally. A monogram is shown if an image cannot load.</small><span class="error" id="linkFormError" role="alert"></span></div></div><div class="form-actions">${deleteButton(existing)}<button type="button" class="secondary close-modal">取消</button><button type="submit" class="primary" id="saveLinkButton">保存网址</button></div></form>`);
 const current=()=>$('#linkForm')?.dataset.modalToken===modalToken&&space===modalSpace;
 const preview=()=>{if(!current())return;let root=$('#linkThumbPreview');root.replaceChildren();if(imageValue){let img=document.createElement('img');img.src=imageValue;img.alt='缩略图预览';img.referrerPolicy='no-referrer';img.onerror=()=>{if(current())root.textContent='图片暂不可用 / Image unavailable.'};root.append(img)}else root.textContent='默认显示站点图标 / Site icon by default.'};preview();
 $('#linkForm [name="url"]').onblur=e=>{if(!$('#linkForm [name="title"]').value.trim()){try{$('#linkForm [name="title"]').placeholder=new URL(normalizedLinkURL(e.target.value)).hostname.replace(/^www\./,'')}catch{}}};
 $('#linkThumbURL').oninput=e=>{let value=e.target.value.trim();if(!value){imageValue='';$('#linkFormError').textContent='';preview();return}if(safeURL(value)==='#'){$('#linkFormError').textContent='请输入 http 或 https 图片链接 / Enter an HTTP or HTTPS image URL.';return}imageValue=value;$('#linkFormError').textContent='';preview()};
 $('#resetLinkThumb').onclick=()=>{imageValue='';$('#linkThumbURL').value='';$('#linkThumbFile').value='';$('#linkFormError').textContent='';preview()};
 $('#linkThumbFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;uploading=true;$('#saveLinkButton').disabled=true;$('#linkFormError').textContent='正在处理图片 / Processing image…';try{let result=await shrinkLinkThumbnail(file);if(!current())return;imageValue=result;$('#linkThumbURL').value='';$('#linkFormError').textContent='';preview()}catch(e){if(current())$('#linkFormError').textContent=e.message}finally{uploading=false;if(current())$('#saveLinkButton').disabled=false}};
 $('#linkForm').onsubmit=e=>{e.preventDefault();if(uploading||!current())return;let form=formData(e.target),url;try{url=normalizedLinkURL(form.url);if($('#linkThumbURL').value&&safeURL($('#linkThumbURL').value)==='#')throw Error('请修正图片链接 / Fix the image URL.')}catch(err){$('#linkFormError').textContent=err.message;return}let title=form.title.trim();if(!title)return;if(!validLinkThumbnail(imageValue))return;let saved={id:item.id||id(),title,url,category:form.category,notes:form.notes,thumbnail:imageValue,addedAt:item.addedAt||day()};let before=data.links;data.links=existing?before.map(x=>x.id===linkId?saved:x):[saved,...before];if(!save()){data.links=before;$('#linkFormError').textContent='保存失败，请先导出备份或减少缩略图 / Storage full. Export a backup or reduce thumbnails.';return}closeModal();render();featureNotice('网址已保存','Website saved.')};
 if(existing)$('#deleteRecord').onclick=()=>confirmDelete('删除这个网址及其缩略图？',()=>{data.links=data.links.filter(x=>x.id!==linkId)})
}
function manageLinkCategories(){ensureLinkLibrary();openModal('管理网址用途分类',`<form id="linkCategoryForm"><label class="field">新分类 / New category<input name="category" required maxlength="30" placeholder="例如：摄影、字体、AIGC"></label><div class="form-actions"><button class="primary">添加分类</button></div></form><div id="linkCategoryList"></div><p class="subtle">只有没有网址的分类可以删除。先编辑网址分类，再删除旧分类。<br>Move links to another category before deleting an occupied category.</p>`);const draw=()=>{$('#linkCategoryList').innerHTML=data.linkCategories.map(c=>`<div class="category-row"><span>${esc(c)} <small>${data.links.filter(x=>x.category===c).length} 个网址</small></span><button class="text-button" data-delete-link-category="${esc(c)}" ${data.links.some(x=>x.category===c)||data.linkCategories.length===1?'disabled':''}>删除</button></div>`).join('');$$('[data-delete-link-category]').forEach(b=>b.onclick=()=>{let before=data.linkCategories;data.linkCategories=before.filter(x=>x!==b.dataset.deleteLinkCategory);if(!save()){data.linkCategories=before;return}draw();render()})};draw();$('#linkCategoryForm').onsubmit=e=>{e.preventDefault();let name=new FormData(e.target).get('category').trim();if(!name)return;if(data.linkCategories.includes(name))return featureNotice('该分类已存在','Category already exists.');if(data.linkCategories.length>=30)return featureNotice('最多支持 30 个分类','Maximum 30 categories.');let before=data.linkCategories;data.linkCategories=[...before,name];if(!save()){data.linkCategories=before;return}e.target.reset();draw();render()}}
function validateLinkBackup(d){let categories=d.linkCategories===undefined?[...defaultLinkCategories]:d.linkCategories;if(!Array.isArray(categories)||!categories.length||categories.length>30||categories.some(x=>typeof x!=='string'||!x.trim()||x.length>30)||new Set(categories).size!==categories.length)throw Error('网址分类格式不正确');let links=d.links||[];if(!Array.isArray(links)||links.length>2000)throw Error('网址数量或格式不正确');let seen=new Set();links=links.map(x=>{if(!x||typeof x.id!=='string'||x.id.length>200||seen.has(x.id))throw Error('网址 ID 不正确');seen.add(x.id);if(typeof x.title!=='string'||!x.title.trim()||x.title.length>100||typeof x.url!=='string'||x.url.length>2000||safeURL(x.url)==='#'||!categories.includes(x.category)||typeof x.notes!=='string'||x.notes.length>12000||typeof x.thumbnail!=='string'||!validLinkThumbnail(x.thumbnail)||(x.thumbnail&&!x.thumbnail.startsWith('data:')&&x.thumbnail.length>2000))throw Error('网址记录或缩略图格式不正确');return {id:x.id,title:x.title,url:x.url,category:x.category,notes:x.notes,thumbnail:x.thumbnail,addedAt:typeof x.addedAt==='string'?x.addedAt.slice(0,10):day()}});return {links,linkCategories:categories}}
